#!/usr/bin/env bash
# ============================================================================
#  apply-static-colors.sh — applies the static "Minimaru" palette
# ----------------------------------------------------------------------------
#  Two uses:
#   1) Bootstrap on a fresh clone: the per-app color files are generated by
#      matugen and do NOT live in the repo — only their *.static.*
#      counterparts do. Running this once after cloning leaves the system
#      with the static identity, identical to how it looks with dynamic
#      theming turned off (the default state).
#   2) Restoration when turning matugen off: hypr/scripts/matugen_toggle.sh
#      calls this same script instead of duplicating the copy list.
#
#  The kitty reload is guarded with "|| true" on purpose: on a freshly
#  installed clone that process isn't running yet, and that shouldn't
#  fail the bootstrap. (There was a swaync reload here too, retired with
#  the rest of its integration in Fase 4, 2026-09-22.)
# ============================================================================

set -u

# La lista de pares estático → vigente, UNA vez (rediseño 12A, 2026-09-28): la usa la copia
# de abajo y la preview de tema del shell (`minimaru/scripts/theme-preview.py`), que la pide con
# `--list` en vez de repetirla. `--list` imprime `copy<TAB>origen<TAB>destino` por par y
# `script<TAB>ruta` por el script de Hyprland, y no toca nada.
# F1a: sólo el destino de la shell sale del árbol de código.
SHELL_DIR="${SUMI_SHELL_DIR:-${XDG_CONFIG_HOME:-$HOME/.config}/quickshell/sumi}"
SHELL_COLORS="${XDG_STATE_HOME:-$HOME/.local/state}/sumi-shell/colors.json"
PAIRS=(
    "$HOME/.config/hyprlock/colors.static.conf"          "$HOME/.config/hyprlock/colors.conf"
    "$HOME/.config/kitty/colors/colors.static.conf"      "$HOME/.config/kitty/colors/colors.conf"
    "$HOME/.config/starship.static.toml"                 "$HOME/.config/starship.toml"
    "$HOME/.config/fish/theme-goldship.static.fish"      "$HOME/.config/fish/conf.d/theme-goldship.fish"
    "$HOME/.config/hyprlock/scripts/music-colors.static.sh" "$HOME/.config/hyprlock/scripts/music-colors.sh"
    "$HOME/.config/gtk-3.0/gtk-colors.static.css"        "$HOME/.config/gtk-3.0/gtk-colors.css"
    "$HOME/.config/gtk-4.0/gtk-colors.static.css"        "$HOME/.config/gtk-4.0/gtk-colors.css"
    "$HOME/.config/qt5ct/colors/minimaru.static.conf" "$HOME/.config/qt5ct/colors/minimaru.conf"
    "$HOME/.config/qt6ct/colors/minimaru.static.conf" "$HOME/.config/qt6ct/colors/minimaru.conf"
    "$SHELL_DIR/colors.static.json" "$SHELL_COLORS"
    "$HOME/.config/hypr/colors.static.lua"                "$HOME/.config/hypr/colors.lua"
)
STATIC_HYPR="$HOME/.config/hypr/scripts/dynamic-colors.static.sh"

if [ "${1:-}" = "--list" ]; then
    for ((i = 0; i < ${#PAIRS[@]}; i += 2)); do
        printf 'copy\t%s\t%s\n' "${PAIRS[i]}" "${PAIRS[i+1]}"
    done
    printf 'script\t%s\n' "$STATIC_HYPR"
    exit 0
fi

mkdir -p "$(dirname "$SHELL_COLORS")" || exit 1

for ((i = 0; i < ${#PAIRS[@]}; i += 2)); do
    cp "${PAIRS[i]}" "${PAIRS[i+1]}" 2>/dev/null || true
done

# The direct static path does not run Matugen hooks. Notify Qt only after
# copying the complete palette set; --list above remains strictly read-only.
for qt_major in 5 6; do
    timeout 5 python3 -B "$SHELL_DIR/scripts/qt-palette-notify.py" \
        --config "$HOME/.config/qt${qt_major}ct/qt${qt_major}ct.conf" \
        --palette "$HOME/.config/qt${qt_major}ct/colors/minimaru.conf" >/dev/null || true
done

[ -x "$STATIC_HYPR" ] && bash "$STATIC_HYPR"

# Acá vivía la recreación del symlink gtk-4.0/theme-base.css, que apuntaba al
# gtk.css del tema GTK de terceros que estuviera activo. Ya no hace falta y se
# quitó: GTKTheme es Adwaita-dark (stock), así que no hay tema externo que
# encadenar — GTK3 lo carga por la env var GTK_THEME y GTK4 lo trae libadwaita
# incorporado. gtk-3.0/gtk.css y gtk-4.0/gtk.css son hoy un único
# @import 'gtk-colors.css', y ese archivo lo escribe el bloque de copias de
# arriba (o matugen, si el dinámico está encendido). Ver
# docs/THEMING.md § GTK theming.

# Hyprlock background: hyprlock/wallpapers/current.png is written by
# apply-wallpaper.sh the first time a wallpaper is chosen. Sumi-Files ships no
# image, so on a fresh install hyprlock falls back to its background colour
# until then.

killall -SIGUSR1 kitty 2>/dev/null || true
